using System.Data;using System.Text.Json;using Forjix.Application.Abstractions.Cash;using Forjix.Application.Abstractions.Sales;using Forjix.Application.Abstractions.Tenancy;using Forjix.Application.Common;using Forjix.Application.Features.Cash;using Forjix.Domain.Entities.Audit;using Forjix.Domain.Entities.Cash;using Forjix.Domain.Enums;using Forjix.Infrastructure.Persistence.Tenant;using Microsoft.EntityFrameworkCore;
namespace Forjix.Infrastructure.Cash;internal sealed class CashStoreFactory(ITenantDbContextFactory contexts):ICashStoreFactory{public ICashStore Create(ResolvedTenantDatabase tenant)=>new CashStore(contexts.Create(tenant));}internal sealed class CashStore(TenantDbContext db):ICashStore{
 public async Task<CashSessionView?>GetCurrentAsync(CancellationToken ct){var s=await Query().SingleOrDefaultAsync(x=>x.Status==CashSessionStatus.Open,ct);return s is null?null:await Map(s,ct);}
 public async Task<CashSessionView>OpenAsync(Guid user,decimal amount,DateTimeOffset now,SalesAuditContext ctx,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{if(await db.CashSessions.AnyAsync(x=>x.Status==CashSessionStatus.Open,ct))throw new ResourceConflictException("Já existe um caixa aberto.");var register=await db.CashRegisters.FirstOrDefaultAsync(x=>x.IsActive,ct);if(register is null){register=new CashRegister{Id=Guid.NewGuid(),Name="Caixa principal"};db.CashRegisters.Add(register);}var s=new CashSession{Id=Guid.NewGuid(),CashRegisterId=register.Id,OpenedByUserId=user,OpenedAt=now,OpeningAmount=amount};s.Movements.Add(new CashMovement{Type=CashMovementType.Opening,Amount=amount,UserId=user,CreatedAt=now});db.CashSessions.Add(s);db.AuditLogs.Add(Audit(AuditAction.CashOpened,s.Id,user,ctx,now,new{Amount=amount}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await Map(await Query().SingleAsync(x=>x.Id==s.Id,ct),ct);}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<CashSessionView>MoveAsync(Guid user,CashMovementType type,decimal amount,string reason,byte[] version,DateTimeOffset now,SalesAuditContext ctx,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);try{var s=await Open(ct);db.Entry(s).Property(x=>x.RowVersion).OriginalValue=version;s.Movements.Add(new CashMovement{Type=type,Amount=amount,Reason=reason,UserId=user,CreatedAt=now});db.AuditLogs.Add(Audit(type==CashMovementType.Supply?AuditAction.CashSupply:AuditAction.CashWithdrawal,s.Id,user,ctx,now,new{Amount=amount,Reason=reason}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await Map(s,ct);}catch(DbUpdateConcurrencyException){await tx.RollbackAsync(ct);throw new ResourceConflictException("O caixa foi alterado por outro usuário.");}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task<CashSessionView>CloseAsync(Guid user,decimal amount,byte[] version,DateTimeOffset now,SalesAuditContext ctx,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);try{var s=await Open(ct);db.Entry(s).Property(x=>x.RowVersion).OriginalValue=version;var expected=Expected(s);var adjustment=amount-expected;if(adjustment!=0)s.Movements.Add(new CashMovement{Type=CashMovementType.ClosingAdjustment,Amount=adjustment,Reason="Diferença no fechamento",UserId=user,CreatedAt=now});s.Close(user,amount,now);db.AuditLogs.Add(Audit(AuditAction.CashClosed,s.Id,user,ctx,now,new{Expected=expected,Closing=amount,Difference=adjustment}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await Map(s,ct);}catch(DbUpdateConcurrencyException){await tx.RollbackAsync(ct);throw new ResourceConflictException("O caixa foi alterado por outro usuário.");}catch{await tx.RollbackAsync(ct);throw;}}
 private Task<CashSession>Open(CancellationToken ct)=>Query().SingleOrDefaultAsync(x=>x.Status==CashSessionStatus.Open,ct).ContinueWith(t=>t.Result??throw new ResourceConflictException("Não existe caixa aberto."),ct,TaskContinuationOptions.ExecuteSynchronously,TaskScheduler.Default);private IQueryable<CashSession>Query()=>db.CashSessions.Include(x=>x.CashRegister).Include(x=>x.Movements);private async Task<CashSessionView>Map(CashSession s,CancellationToken ct){var ids=s.Movements.Select(x=>x.UserId).Append(s.OpenedByUserId).Distinct().ToList();var names=await db.Users.Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.Name,ct);return new(s.Id,s.CashRegister.Name,s.Status.ToString(),s.OpeningAmount,Expected(s),s.ClosingAmount,names.GetValueOrDefault(s.OpenedByUserId,"Usuário"),s.OpenedAt,s.ClosedAt,Convert.ToBase64String(s.RowVersion),s.Movements.OrderByDescending(x=>x.CreatedAt).Select(x=>new CashMovementItem(x.Id,x.Type.ToString(),x.Amount,x.Reason,names.GetValueOrDefault(x.UserId,"Usuário"),x.CreatedAt,x.SaleId)).ToList());}private static decimal Expected(CashSession s)=>s.Movements.Sum(x=>x.Type switch{CashMovementType.Opening or CashMovementType.Sale or CashMovementType.Supply=>x.Amount,CashMovementType.Withdrawal=>-x.Amount,CashMovementType.ClosingAdjustment=>x.Amount,_=>0});private static AuditLog Audit(AuditAction action,Guid id,Guid user,SalesAuditContext ctx,DateTimeOffset now,object data)=>new(){UserId=user,Action=action,EntityName=nameof(CashSession),EntityId=id.ToString(),AfterData=JsonSerializer.Serialize(data),CorrelationId=ctx.CorrelationId,IpAddress=ctx.IpAddress,OccurredAt=now};public ValueTask DisposeAsync()=>db.DisposeAsync();}
